// @vitest-environment node
/**
 * SPEC-062: ciclo de vida de las ventanas desacopladas
 * (src/main/detachedWindows.ts) con `electron` mockeado — clase BrowserWindow
 * falsa que registra opciones de construcción, listeners y llamadas. Cubre la
 * parte automatizable de los ACs de «Ventanas nativas» (opciones con las que
 * main pide la ventana, deduplicación con foco, título compuesto y su
 * fallback, neutralización de `page-title-updated`) y el cierre en bloque.
 * La geometría real, el foco efectivo y el título en la barra nativa son
 * MANUAL (sin e2e en el proyecto).
 * Generated by QA Dev agent.
 */
import { beforeEach, describe, expect, it, vi } from 'vitest'
import { openDetachedWindow, closeDetachedWindows } from '../../../src/main/detachedWindows'
import { getDetachedWindow, listDetachedWindows } from '../../../src/main/detachedWindowRegistry'
import * as repository from '../../../src/main/db/repository'

interface WindowOptions {
  width: number
  height: number
  minWidth: number
  minHeight: number
  show: boolean
  autoHideMenuBar: boolean
  title: string
  alwaysOnTop?: boolean
  parent?: unknown
  webPreferences: { preload: string; sandbox: boolean }
}

const harness = vi.hoisted(() => {
  class FakeBrowserWindow {
    static instances: FakeBrowserWindow[] = []
    readonly options: WindowOptions
    readonly listeners = new Map<string, Array<(...args: unknown[]) => void>>()
    readonly loadFileCalls: Array<{ path: string; options?: { hash?: string } }> = []
    readonly loadUrlCalls: string[] = []
    readonly webContents = {
      isDestroyed: (): boolean => false,
      setWindowOpenHandler: vi.fn(),
      send: vi.fn()
    }
    destroyed = false
    minimized = false
    shown = false
    focusCalls = 0
    restoreCalls = 0
    closeCalls = 0

    constructor(options: WindowOptions) {
      this.options = options
      FakeBrowserWindow.instances.push(this)
    }

    on(event: string, listener: (...args: unknown[]) => void): this {
      const current = this.listeners.get(event) ?? []
      current.push(listener)
      this.listeners.set(event, current)
      return this
    }

    emit(event: string, ...args: unknown[]): void {
      for (const listener of this.listeners.get(event) ?? []) {
        listener(...args)
      }
    }

    isDestroyed(): boolean {
      return this.destroyed
    }

    isMinimized(): boolean {
      return this.minimized
    }

    restore(): void {
      this.restoreCalls += 1
      this.minimized = false
    }

    focus(): void {
      this.focusCalls += 1
    }

    show(): void {
      this.shown = true
    }

    close(): void {
      this.closeCalls += 1
      this.destroyed = true
      this.emit('closed')
    }

    loadFile(path: string, options?: { hash?: string }): Promise<void> {
      this.loadFileCalls.push({ path, options })
      return Promise.resolve()
    }

    loadURL(url: string): Promise<void> {
      this.loadUrlCalls.push(url)
      return Promise.resolve()
    }
  }
  return { FakeBrowserWindow, isDev: false, openExternal: vi.fn() }
})

vi.mock('electron', () => ({
  BrowserWindow: harness.FakeBrowserWindow,
  shell: { openExternal: harness.openExternal }
}))

vi.mock('@electron-toolkit/utils', () => ({
  is: {
    get dev(): boolean {
      return harness.isDev
    }
  }
}))

vi.mock('../../../src/main/db/repository', () => ({
  getInterview: vi.fn()
}))

function instances(): InstanceType<typeof harness.FakeBrowserWindow>[] {
  return harness.FakeBrowserWindow.instances
}

function last(): InstanceType<typeof harness.FakeBrowserWindow> {
  const value = instances().at(-1)
  if (value === undefined) {
    throw new Error('No se construyó ninguna ventana')
  }
  return value
}

beforeEach(() => {
  vi.clearAllMocks()
  harness.FakeBrowserWindow.instances.length = 0
  harness.isDev = false
  delete process.env['ELECTRON_RENDERER_URL']
  closeDetachedWindows()
  vi.mocked(repository.getInterview).mockReturnValue({
    id: 'i-1',
    title: 'Discovery con Acme'
  } as ReturnType<typeof repository.getInterview>)
})

describe('detachedWindows (SPEC-062)', () => {
  it('creates a normal resizable window with the spec geometry and the composed title', () => {
    openDetachedWindow('assistant', 'i-1')

    expect(instances()).toHaveLength(1)
    const { options } = last()
    expect(options.width).toBe(420)
    expect(options.height).toBe(640)
    expect(options.minWidth).toBe(360)
    expect(options.minHeight).toBe(480)
    expect(options.title).toBe('Asistente — Discovery con Acme')
    expect(options.show).toBe(false)
    expect(options.autoHideMenuBar).toBe(true)
    // Ventana NORMAL: ni always-on-top (territorio de SPEC-054) ni hija de la
    // principal (una hija quedaría siempre por encima, lo contrario del mosaico)
    expect(options.alwaysOnTop).toBeUndefined()
    expect(options.parent).toBeUndefined()
    expect(options.webPreferences.sandbox).toBe(false)
    expect(options.webPreferences.preload).toContain('preload')
  })

  it('composes the script window title with its own prefix', () => {
    openDetachedWindow('script', 'i-1')

    expect(last().options.title).toBe('Guión — Discovery con Acme')
  })

  it('falls back to the bare prefix when the interview cannot be read', () => {
    vi.mocked(repository.getInterview).mockImplementation(() => {
      throw new Error('Entrevista no encontrada')
    })

    openDetachedWindow('assistant', 'i-borrada')

    // Una entrevista ilegible nunca impide abrir la ventana
    expect(instances()).toHaveLength(1)
    expect(last().options.title).toBe('Asistente')
  })

  it('loads the shared hash route of the component in production', () => {
    openDetachedWindow('script', 'i-1')

    expect(last().loadFileCalls).toHaveLength(1)
    expect(last().loadFileCalls[0].options).toEqual({ hash: '/detached/script/i-1' })
    expect(last().loadUrlCalls).toEqual([])
  })

  it('loads the dev renderer URL with the same hash when running in dev', () => {
    harness.isDev = true
    process.env['ELECTRON_RENDERER_URL'] = 'http://localhost:5173'

    openDetachedWindow('assistant', 'i-1')

    expect(last().loadUrlCalls).toEqual(['http://localhost:5173/#/detached/assistant/i-1'])
    expect(last().loadFileCalls).toEqual([])
  })

  it('neutralizes the document title so the native title survives the load', () => {
    openDetachedWindow('assistant', 'i-1')
    const window = last()
    const event = { preventDefault: vi.fn() }

    window.emit('page-title-updated', event)

    expect(event.preventDefault).toHaveBeenCalledTimes(1)
  })

  it('shows the window only when it is ready to show', () => {
    openDetachedWindow('assistant', 'i-1')
    expect(last().shown).toBe(false)

    last().emit('ready-to-show')

    expect(last().shown).toBe(true)
  })

  it('does not create a second window for the same component: it restores and focuses the existing one', () => {
    openDetachedWindow('assistant', 'i-1')
    const first = last()
    first.minimized = true

    openDetachedWindow('assistant', 'i-1')

    expect(instances()).toHaveLength(1)
    expect(first.restoreCalls).toBe(1)
    expect(first.focusCalls).toBe(1)
  })

  it('does not restore a window that is not minimized, but still focuses it', () => {
    openDetachedWindow('script', 'i-1')
    const first = last()

    openDetachedWindow('script', 'i-1')

    expect(first.restoreCalls).toBe(0)
    expect(first.focusCalls).toBe(1)
  })

  it('keeps one window per component: both coexist', () => {
    openDetachedWindow('assistant', 'i-1')
    openDetachedWindow('script', 'i-1')

    expect(instances()).toHaveLength(2)
    expect(listDetachedWindows()).toHaveLength(2)
  })

  it('unregisters the window when the user closes it, so its button reopens a fresh one', () => {
    openDetachedWindow('assistant', 'i-1')
    const first = last()

    first.emit('closed')
    expect(getDetachedWindow('assistant')).toBeNull()

    openDetachedWindow('assistant', 'i-1')
    expect(instances()).toHaveLength(2)
    expect(last()).not.toBe(first)
  })

  it('sends external links from the detached window to the browser', () => {
    openDetachedWindow('script', 'i-1')
    const handler = vi.mocked(last().webContents.setWindowOpenHandler).mock
      .calls[0][0] as (details: { url: string }) => { action: string }

    expect(handler({ url: 'https://maurya.app' })).toEqual({ action: 'deny' })
    expect(harness.openExternal).toHaveBeenCalledWith('https://maurya.app')
  })

  it('closes every detached window and empties the registry, and is idempotent', () => {
    openDetachedWindow('assistant', 'i-1')
    openDetachedWindow('script', 'i-1')
    const [assistantWindow, scriptWindow] = instances()

    closeDetachedWindows()

    expect(assistantWindow.closeCalls).toBe(1)
    expect(scriptWindow.closeCalls).toBe(1)
    expect(listDetachedWindows()).toEqual([])
    expect(() => closeDetachedWindows()).not.toThrow()
    expect(assistantWindow.closeCalls).toBe(1)
  })

  it('never reuses a destroyed window', () => {
    openDetachedWindow('assistant', 'i-1')
    const first = last()
    first.destroyed = true

    openDetachedWindow('assistant', 'i-1')

    expect(instances()).toHaveLength(2)
    expect(first.focusCalls).toBe(0)
  })
})
